document.addEventListener("DOMContentLoaded",()=>{const t=document.body,e=document.getElementById("toc-toggle");if(!e)return;e.checked=document.documentElement.classList.contains("toc-open"),window.addEventListener("keydown",t=>{const n=document.activeElement?.tagName.toLowerCase();if(t.ctrlKey||t.metaKey||t.altKey||t.shiftKey)return;if(t.key.toLowerCase()!=="c")return;if(n==="input"&&document.activeElement?.type!=="checkbox"||n==="textarea"||document.activeElement?.isContentEditable)return;t.preventDefault(),t.stopPropagation(),e.checked=!e.checked,e.dispatchEvent(new Event("change"))},!0),e.addEventListener("change",function(){this.checked?(document.documentElement.classList.add("toc-open"),localStorage.setItem("tocOpen","true")):(document.documentElement.classList.remove("toc-open"),localStorage.setItem("tocOpen","false"))})})